/* Internal: the passphrase rules with an explicit blocklist, and the word list. */
#ifndef GAZPACHO_SC_PASS_H
#define GAZPACHO_SC_PASS_H

#include "gz_storage_crypto.h"

#define GZ_SC_EFF_WORDS 7776
#define GZ_SC_EFF_WORD_MAX 9
/* SHA-256 of the words joined by newlines (printed by the generator). */
#define GZ_SC_EFF_DIGEST_HEX "abae49761b88f3f1ba31ef944bea1f61b795a3cd7e1cfb7d276ed45bf77967ba"

/* The EFF large word list (sc_wordlist.c, generated by
 * tools/gen-eff-wordlist.py; source and licence in that file). */
extern const char *const gz_sc_eff_words[GZ_SC_EFF_WORDS];

/* The bundled blocklist (sc_blocklist.c, generated by tools/gen-blocklist.py;
 * source, licence and the reason only entries of 15 characters or more are
 * kept are in that file): lowercase ASCII, sorted bytewise, no duplicates. */
#define GZ_SC_BLOCK_N 10898
#define GZ_SC_BLOCK_DIGEST_HEX "97733f3bb498169430477a36d9b3afb364e68f09af4ddaa28aa956445807931a"
extern const char *const gz_sc_blocklist[GZ_SC_BLOCK_N];

/* 4.1's rules with an explicit blocklist (compared after case folding each
 * entry, linearly; for tests). blocklist NULL: the bundled one. */
gz_sc_pass_rule_t sc_pass_check_list(const uint8_t *nfc, size_t len, const char *wallet_name,
                                     const char *const *words, size_t n_words, const char *const *blocklist,
                                     size_t n_block);

#endif
